function audited(_t: object, k: string | symbol, d: PropertyDescriptor) {
  const original = d.value;
  d.value = function (...args: unknown[]) {
    const action = String(k);
    sink.record(currentSubject(), action, 'attempt');
    try { const r = original.apply(this, args); sink.record(currentSubject(), action, 'ok'); return r; }
    catch (e) { sink.record(currentSubject(), action, 'failed'); throw e; }
  };
  return d;
}
// usage: class Payments { @audited pay(p: Payment) { ... } }
